CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,city TEXT NOT NULL,neighborhood TEXT NOT NULL DEFAULT '',cep TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',account_type TEXT NOT NULL DEFAULT 'person' CHECK(account_type IN ('person','business')),business_name TEXT NOT NULL DEFAULT '',cnpj TEXT NOT NULL DEFAULT '',interests_json TEXT NOT NULL DEFAULT '[]',avatar TEXT NOT NULL DEFAULT '',rating DOUBLE PRECISION NOT NULL DEFAULT 0,donations INTEGER NOT NULL DEFAULT 0 CHECK(donations>=0),received INTEGER NOT NULL DEFAULT 0 CHECK(received>=0),carbon_saved_percent INTEGER NOT NULL DEFAULT 0,achievements_json TEXT NOT NULL DEFAULT '[]',role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),suspended BOOLEAN NOT NULL DEFAULT false,notification_preferences_json TEXT NOT NULL DEFAULT '[]',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),last_active_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL CHECK(length(title)<=140),description TEXT NOT NULL CHECK(length(description)<=3000),category TEXT NOT NULL,condition TEXT NOT NULL,goal TEXT NOT NULL,image_url TEXT NOT NULL,likes INTEGER NOT NULL DEFAULT 0 CHECK(likes>=0),comments INTEGER NOT NULL DEFAULT 0 CHECK(comments>=0),location TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,chip_icon TEXT NOT NULL,chip_label TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Disponível' CHECK(status IN ('Disponível','Reservado','Doado','Trocado','Encerrado')),reserved_by TEXT REFERENCES users(id),completed_with TEXT REFERENCES users(id),completed_at TIMESTAMPTZ,views INTEGER NOT NULL DEFAULT 0 CHECK(views>=0),updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS threads (id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,participants_json TEXT NOT NULL,unread_count INTEGER NOT NULL DEFAULT 0,last_message_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE,sender_id TEXT NOT NULL REFERENCES users(id),text TEXT NOT NULL CHECK(length(text)<=1000),sent_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS negotiations (id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id),interested_id TEXT NOT NULL REFERENCES users(id),thread_id TEXT REFERENCES threads(id),status TEXT NOT NULL DEFAULT 'interested' CHECK(status IN ('interested','reserved','completed','cancelled')),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,UNIQUE(post_id,interested_id));
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id),text TEXT NOT NULL CHECK(length(text)<=500),created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS post_likes (post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(post_id,user_id));
CREATE TABLE IF NOT EXISTS favorites (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(user_id,post_id));
CREATE TABLE IF NOT EXISTS auth_identities (provider TEXT NOT NULL,provider_subject TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,email_at_linked TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(provider,provider_subject),UNIQUE(provider,user_id));
CREATE TABLE IF NOT EXISTS post_views (post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,viewed_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(post_id,user_id));
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY,negotiation_id TEXT NOT NULL REFERENCES negotiations(id) ON DELETE CASCADE,reviewer_id TEXT NOT NULL REFERENCES users(id),reviewee_id TEXT NOT NULL REFERENCES users(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL,UNIQUE(negotiation_id,reviewer_id));
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT NOT NULL,text TEXT NOT NULL,link TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL,read_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES users(id),target_type TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL,reviewed_at TIMESTAMPTZ,reviewed_by TEXT REFERENCES users(id),UNIQUE(reporter_id,target_type,target_id));
CREATE TABLE IF NOT EXISTS blocked_users (blocker_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));
CREATE TABLE IF NOT EXISTS collection_points (id TEXT PRIMARY KEY,name TEXT NOT NULL,categories_json TEXT NOT NULL,hours TEXT NOT NULL,location TEXT NOT NULL,status TEXT NOT NULL,origin TEXT NOT NULL DEFAULT 'ReUsa+',last_updated TIMESTAMPTZ,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS collection_point_suggestions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,categories_json TEXT NOT NULL,hours TEXT NOT NULL DEFAULT '',location TEXT NOT NULL,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL,reviewed_at TIMESTAMPTZ,reviewed_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS inspiration_products (id TEXT PRIMARY KEY,creator_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,material TEXT NOT NULL,price TEXT NOT NULL,city TEXT NOT NULL,image_url TEXT NOT NULL,description TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS event_outbox (id TEXT PRIMARY KEY,type TEXT NOT NULL,payload_json TEXT NOT NULL,correlation_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0,locked_by TEXT,locked_until TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),last_error TEXT);
CREATE INDEX IF NOT EXISTS posts_feed_idx ON posts(created_at DESC); CREATE INDEX IF NOT EXISTS posts_author_idx ON posts(author_id); CREATE INDEX IF NOT EXISTS messages_thread_idx ON messages(thread_id,sent_at); CREATE INDEX IF NOT EXISTS negotiations_post_idx ON negotiations(post_id,status); CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id,created_at DESC); CREATE INDEX IF NOT EXISTS outbox_pending_idx ON event_outbox(created_at) WHERE published_at IS NULL;
